window.ENAMED_LOCAL_QUESTION_BANK=window.ENAMED_LOCAL_QUESTION_BANK||{};window.ENAMED_LOCAL_QUESTION_BANK["med:med-gineco-e-obstetricia-med-gin-04"]={"block":"med:med-gineco-e-obstetricia-med-gin-04","label":"MED · MED GIN 04","count":74,"questions":[{"id":"med-gineco-e-obstetricia-med-gin-04-227261","number":"227261","sourceNumber":"227261","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-04","collectionLabel":"MED · MED GIN 04","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 04","subtopic":"","stem":"Paciente de 22 anos, com ciclos oligomenorreicos desde a menarca, acne e hirsutismo,\nem que a avaliação laboratorial mostra LH\n(Hormônio Luteinizante) duas vezes o valor do FSH\n(Hormônio Folículo Estimulante) e índice de HOMA (Homeostatic Model Assessment) compatível\ncom hiperinsulinemia. O provável diagnóstico é:","options":{"A":"Síndrome do ovário policísticos (anovulação crônica).","B":"Hiperplasia adrenal congênita.","C":"Tumor ovariano produtor de androgênios.","D":"Tumor de células da granulosa."},"answer":"A","source":"Gineco e obstetricia/MED GIN 04/MED GIN 04.txt","sourceLabel":"MED · MED GIN 04","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-04-243003","number":"243003","sourceNumber":"243003","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-04","collectionLabel":"MED · MED GIN 04","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 04","subtopic":"","stem":"Uma mulher de 20 anos de idade procurou o serviço de ginecologia endócrina com\nquadro de amenorreia primária. Além disso, referiu ausência de pelos em região de axila e\ngenitália. Exames mostraram ?hCG negativo e prolactina normais e cariótipo 46 XY. Na\nultrassonografia transvaginal, útero não caracterizado. Assinale a alternativa que apresenta o\nprovável diagnóstico:","options":{"A":"síndrome dos ovários policísticos.","B":"síndrome de Kallmann.","C":"síndrome de Asherman.","D":"síndrome de Morris.","E":"síndrome de Mayer?Rokitansky?Kuster?Hauser."},"answer":"D","source":"Gineco e obstetricia/MED GIN 04/MED GIN 04.txt","sourceLabel":"MED · MED GIN 04","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-04-243005","number":"243005","sourceNumber":"243005","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-04","collectionLabel":"MED · MED GIN 04","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 04","subtopic":"","stem":"Uma mulher de 22 anos de idade procurou o serviço de saúde com queixa de\nirregularidade menstrual, associada a\nhiperandrogenismo (acne e hisurtismo). Sua ultrassonografia\napresentou útero com volume normal, eco endometrial sem alterações e ovários com volumes\naumentados e padrão policístico.","options":{"A":"caso a paciente em questão não apresentasse irregularidade menstrual, o diagnóstico da\nsíndrome dos ovários policísticos ainda poderia ser considerado.","B":"o critério ultrassonográfico é considerado como positivo na presença de ambos os ovários\nalterados. Caso a paciente em questão\napresentasse apenas um ovário alterado, esse critério não\nseria positivo.","C":"o hiperandrogenismo é obrigatório para o diagnóstico da síndrome dos ovários policísticos.","D":"trata-se de paciente jovem. Sendo assim, não há a necessidade de se excluir outras patologias\nantes da confirmação de que ela tem o\ndiagnóstico da síndrome dos ovários policísticos.","E":"a presença de acne só será valorizada caso a paciente apresente androgênios séricos\naumentados."},"answer":"A","source":"Gineco e obstetricia/MED GIN 04/MED GIN 04.txt","sourceLabel":"MED · MED GIN 04","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-04-199535","number":"199535","sourceNumber":"199535","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-04","collectionLabel":"MED · MED GIN 04","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 04","subtopic":"","stem":"Em relação ao desenvolvimento sexual feminino, assinale a alternativa INCORRETA:","options":{"A":"A causa mais comum da Hiperplasia Adrenal\nCongênita (HAC) é a deficiência de 21-\nhidroxilase (46, XX), apresentando risco\nsignificativo de crise adrenal (forma perdedora de\n\nsal) e, caso não seja diagnosticada e tratada, vômitos, diarreia, hipotensão e choque hipovolêmico\npodem ocorrer entre 10 a 20 dias de vida.","B":"A crise adrenal também pode ocorrer em alguns outros tipos de HAC, incluindo a deficiência de\n11-beta-hidroxilase.","C":"Qualquer recém-nascido que apresente genitália\natípica e gônadas não palpáveis, deve ser\nconsiderado portador de HAC e monitorado\n\nquanto à perda de sal e crise adrenal até que o diagnóstico seja excluído.","D":"Uma vantagem de adiar a cirurgia é que ela mantém opções abertas para mulheres virilizadas\nde 46, XX, caso elas tenham uma identidade de\ngênero masculina, o que ocorre em cerca de 30%\nde 46, XX."},"answer":"D","source":"Gineco e obstetricia/MED GIN 04/MED GIN 04.txt","sourceLabel":"MED · MED GIN 04","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-04-199538","number":"199538","sourceNumber":"199538","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-04","collectionLabel":"MED · MED GIN 04","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 04","subtopic":"","stem":"São formas raras de genitálias atípicas no desenvolvimento sexual, EXCETO:","options":{"A":"Distúrbios do desenvolvimento sexual (46, XY)\npor deficiência de 17-beta- hidroxiesteroide.","B":"Distúrbios do desenvolvimento sexual (46, XY),\npor deficiência de 5-alfa redutase.","C":"Distúrbios do desenvolvimento sexual (46, XY)\npor insensibilidade ao receptor androgênico.","D":"Distúrbios do desenvolvimento sexual (46, XY)\n\ncom anomalias genitais severas (micropênis, hipertrofia do clitóris, agenesia peniana e extrofia\ncloacal e ovotesticular)."},"answer":"D","source":"Gineco e obstetricia/MED GIN 04/MED GIN 04.txt","sourceLabel":"MED · MED GIN 04","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-04-196740","number":"196740","sourceNumber":"196740","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-04","collectionLabel":"MED · MED GIN 04","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 04","subtopic":"","stem":"A amenorréia primária esta relacionada com:","options":{"A":"Criptomenorreia.","B":"Disgenesia gonadal.","C":"S. Sheehan.","D":"S. Asherman."},"answer":"B","source":"Gineco e obstetricia/MED GIN 04/MED GIN 04.txt","sourceLabel":"MED · MED GIN 04","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-04-196751","number":"196751","sourceNumber":"196751","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-04","collectionLabel":"MED · MED GIN 04","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 04","subtopic":"","stem":"A síndrome de Sheeham está associada:","options":{"A":"Lesão tumoral hipófise.","B":"Lesão tumoral hipofalamo.","C":"Hipovolemia aguda.","D":"Hipovolemia crônica."},"answer":"C","source":"Gineco e obstetricia/MED GIN 04/MED GIN 04.txt","sourceLabel":"MED · MED GIN 04","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-04-199542","number":"199542","sourceNumber":"199542","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-04","collectionLabel":"MED · MED GIN 04","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 04","subtopic":"","stem":"Em relação ao hirsutismo, é INCORRETO afirmar:","options":{"A":"Hirsutismo tem como definição o crescimento excessivo de pêlos terminais em áreas de\ndistribuição feminina.","B":"Hirsutismo pode resultar do excesso de androgênio produzido pelos ovários e/ou adrenais.","C":"Hirsutismo pode resultar do aumento da sensibilidade cutânea aos androgênios.","D":"A causa mais comum de hirsutismo é a síndrome do ovário policístico."},"answer":"A","source":"Gineco e obstetricia/MED GIN 04/MED GIN 04.txt","sourceLabel":"MED · MED GIN 04","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-04-215161","number":"215161","sourceNumber":"215161","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-04","collectionLabel":"MED · MED GIN 04","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 04","subtopic":"","stem":"Mulher com amenorreia secundária não apresenta sangramento por interrupção\nhormonal após estímulo com progesterona, nem\napós estímulo com medicamento constituído por\nestrogênios e progesterona. É provável que ela apresente:","options":{"A":"Tumor hipofisário.","B":"Sinéquia uterina.","C":"Ovários policísticos.","D":"Tumor hipotalâmico.","E":"Tumor da adrenal."},"answer":"B","source":"Gineco e obstetricia/MED GIN 04/MED GIN 04.txt","sourceLabel":"MED · MED GIN 04","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-04-212972","number":"212972","sourceNumber":"212972","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-04","collectionLabel":"MED · MED GIN 04","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 04","subtopic":"","stem":"Caso uma mulher se encontre em amenorreia, é correto afirmar que quando o teste da\nprogesterona:","options":{"A":"É positivo, sugere que ocorreu ovulação.","B":"É positivo, implica em bom nível estrogênico circulante.","C":"É negativo, implica em anormalidade do trato genital inferior.","D":"É positivo após a administração de estrogênio, indica fator uterino.","E":"Persiste negativo após administração de estrogênio, sugere agenesia de útero."},"answer":"B","source":"Gineco e obstetricia/MED GIN 04/MED GIN 04.txt","sourceLabel":"MED · MED GIN 04","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-04-212898","number":"212898","sourceNumber":"212898","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-04","collectionLabel":"MED · MED GIN 04","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 04","subtopic":"","stem":"Jovem de 19 anos, menarca aos 13 anos, refere ter ovários polimicrocisticos. Para este\ndiagnóstico ser estabelecido, segundo os critérios de Rotterdam, quais características devem estar\npresentes?","options":{"A":"Ecografia apresentando ovário aumentado de tamanho (maior que 10 cm³) ou multifolicular (mais\nde 12 folículos pequenos).","B":"Duas das três características a seguir: irregularidade menstrual, ecografia com ovário\nmultifolicular ou aumento do volume, hirsutismo ou acne.","C":"As três características a seguir: irregularidade menstrual, ecografia com ovário multifolicular\nou\naumento do volume, hirsutismo ou acne.","D":"Nesta idade o diagnóstico de SOP não existe e o diagnóstico correto é imaturidade axial.","E":"Amenorreia hipotalâmica, hiperprolactinemia, hirsutismo."},"answer":"B","source":"Gineco e obstetricia/MED GIN 04/MED GIN 04.txt","sourceLabel":"MED · MED GIN 04","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-04-187436","number":"187436","sourceNumber":"187436","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-04","collectionLabel":"MED · MED GIN 04","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 04","subtopic":"","stem":"Constitui-se causa de amenorreia primária de origem canalicular:","options":{"A":"Hiperplasia congênita da Adrenal.","B":"Deficiência da 17- Hidroxilase.","C":"Síndrome de Mayer- Rokitansky.","D":"Síndrome de Morris.","E":"Disgenesia gonadal Mista, XY."},"answer":"C","source":"Gineco e obstetricia/MED GIN 04/MED GIN 04.txt","sourceLabel":"MED · MED GIN 04","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-04-187496","number":"187496","sourceNumber":"187496","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-04","collectionLabel":"MED · MED GIN 04","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 04","subtopic":"","stem":"Sobre os estados intersexuais, NÃO podemos afirmar:","options":{"A":"A digenesia gonadal é constituída por indivíduos portadores de gônadas em fita, entre estes,\npodemos citar a Síndrome de Turner.","B":"Entre os estigmas turnerianos estão a baixa estatura, implantação baixa de cabelos e pescoço\ncurto.","C":"A principal causa de pseudo-hermafroditismo masculino é a hiperplasia congênita da supra\nrenal.","D":"No pseudo-hermafroditismo feminino há graus variáveis de virilização da genitália.","E":"Entre as causas de pseudo hermafroditismo masculino podemos citar a deficiência da 20,22\ndesmolase e a deficiência da 17 alfa hidrolase."},"answer":"C","source":"Gineco e obstetricia/MED GIN 04/MED GIN 04.txt","sourceLabel":"MED · MED GIN 04","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-04-155358","number":"155358","sourceNumber":"155358","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-04","collectionLabel":"MED · MED GIN 04","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 04","subtopic":"","stem":"Sobre a Síndrome dos Ovários Policísticos (SOP) pode-se afirmar, EXCETO:","options":{"A":"A dosagem do LH e a relação LH/FSH são critérios de diagnóstico.","B":"O uso do acetato de ciproterona com etinil-estradiol acarreta supressão do hiperandrogenismo\ncom melhora dos sintomas da SOP.","C":"O citrato de clomifeno é uma opção terapêutica para as mulheres que desejam engravidar.","D":"A flutamida isolada ou associada ao anticoncepcional hormonal oral é uma opção terapêutica\neficaz.","E":"A espironolactona pode ser ministrada em casos de hirsutismo."},"answer":"A","source":"Gineco e obstetricia/MED GIN 04/MED GIN 04.txt","sourceLabel":"MED · MED GIN 04","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-04-148598","number":"148598","sourceNumber":"148598","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-04","collectionLabel":"MED · MED GIN 04","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 04","subtopic":"","stem":"Paciente de 22 anos atendida com amenorréia primária, hirsutismo e dosagens\nelevadas de testosterona total, sulfato de dehidroepiandrosterona (SDHEA) e\n\n17-hidroxiprogesterona. Qual a principal hipótese diagnóstica?","options":{"A":"Tumor ovariano produtor de androgênios.","B":"Tumor de supra-renal.","C":"Macroadenomahipofisário.","D":"Hiperplasia congênita da supra-renal.","E":"Síndrome dos Ovários Policísticos."},"answer":"D","source":"Gineco e obstetricia/MED GIN 04/MED GIN 04.txt","sourceLabel":"MED · MED GIN 04","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-04-162553","number":"162553","sourceNumber":"162553","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-04","collectionLabel":"MED · MED GIN 04","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 04","subtopic":"","stem":"São consideradas malformações de origem mulleriana, EXCETO:","options":{"A":"Síndrome de Mayer-Rokitansky- Kuster?Hauser.","B":"Útero bicorno.","C":"Útero didelfus.","D":"Útero septado.","E":"Síndrome de Morris."},"answer":"E","source":"Gineco e obstetricia/MED GIN 04/MED GIN 04.txt","sourceLabel":"MED · MED GIN 04","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-04-162555","number":"162555","sourceNumber":"162555","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-04","collectionLabel":"MED · MED GIN 04","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 04","subtopic":"","stem":"Constitui importante causa de Pseudo-hermafroditismo Feminino:","options":{"A":"Síndrome de Mayer- Rokitansky.","B":"Síndrome de Morris.","C":"Hiperplasia congênita da Adrenal.","D":"Disgenesia gonadal Mista, XY.","E":"Deficiência da 17- Hidroxilase."},"answer":"C","source":"Gineco e obstetricia/MED GIN 04/MED GIN 04.txt","sourceLabel":"MED · MED GIN 04","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-04-148564","number":"148564","sourceNumber":"148564","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-04","collectionLabel":"MED · MED GIN 04","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 04","subtopic":"","stem":"Observe as afirmativas abaixo e assinale qual não está relacionada à Síndrome dos\nOvários Policísticos (SOP):","options":{"A":"Aumento do risco relativo para câncer de mama.","B":"Aumento do risco relativo para diabetes.","C":"Aumento do risco relativo para câncer de ovário.","D":"Aumento do risco relativo para doenças cardiovasculares.","E":"Aumento do risco relativo para câncer de endométrio."},"answer":"C","source":"Gineco e obstetricia/MED GIN 04/MED GIN 04.txt","sourceLabel":"MED · MED GIN 04","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-04-148586","number":"148586","sourceNumber":"148586","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-04","collectionLabel":"MED · MED GIN 04","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 04","subtopic":"","stem":"Paciente de 38 anos, atrasos menstruais há 02 anos, foi internada com abortamento\nretido e submetida à curetagem pós-aborto.\nApresentou amenorréia de 06 meses após a\ncuretagem. Após teste de gravidez negativo foi feita a prova da progesterona e a paciente não\nmenstruou. Feito então Estradiol na dose de 02 mg por 21 dias com progesterona nos últimos 10\ndias e a paciente menstruou fluxo normal. Depois exames revelaram: TSH 2,875 mUI/ml, prolactina:\n15 ng/ml, LH: 32 mUI/ml e FSH: 46,5 mUI/ml. Qual a hipótese diagnóstica?","options":{"A":"Síndrome da anovulação crônica.","B":"Síndrome de Asherman.","C":"Menopausa precoce.","D":"Síndrome de Sheehan.","E":"Amenorréia de causa hipotalâmica"},"answer":"C","source":"Gineco e obstetricia/MED GIN 04/MED GIN 04.txt","sourceLabel":"MED · MED GIN 04","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-04-126882","number":"126882","sourceNumber":"126882","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-04","collectionLabel":"MED · MED GIN 04","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 04","subtopic":"","stem":"Em relação às más-formações da vagina, assinale a alternativa INCORRETA.","options":{"A":"O septo vaginal transverso resulta da falha da fusão ou canalização do seio urogenital e dos\nductos mulerianos.","B":"A presença do septo vaginal ocorre em 1 a cada 30.000 à 80.000 mulheres.","C":"A síndrome de Mayer-Rokitansky-Küster-Hauser (MRKH) refere-se à ausência congênita da\nvagina com desenvolvimento uterino variável.","D":"O diagnóstico baseia-se na amenorreia primária devido à obstrução total do canal vaginal."},"answer":"A","source":"Gineco e obstetricia/MED GIN 04/MED GIN 04.txt","sourceLabel":"MED · MED GIN 04","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-04-127226","number":"127226","sourceNumber":"127226","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-04","collectionLabel":"MED · MED GIN 04","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 04","subtopic":"","stem":"Todas as sentenças abaixo referem-se a Amenorreia Primária. Identifique as\nVerdadeiras (V) e as Falsas (F). I. Nos casos\nde hipogonadismo, a dosagem de estradiol e\nprogesterona pode indicar se o problema é central ou ovariano. II. Pacientes com hipogonadismo\nhipergonadotrófico devem ser avaliadas com cariótipo, pois a etiologia pode ser a disgenesia\ngonadal. III. Se a paciente apresentar desenvolvimento de mamas e ausência de útero e vagina, o\ncariótipo pode diferenciar agenesia mülleriana de insensibilidade androgênica. IV. Pacientes com\ndeficiência de GnRH apresentam hipogonadismo hipergonadotrófico. V. Hímen imperfurado pode\nser causa de amenorreia se a paciente não tem hipogonadismo. Assinale a opção CORRETA:","options":{"A":"F - V - V - F - V.","B":"V - F - V - V - F.","C":"V - V - V - F - V.","D":"F - V - V - V - V.","E":"F - F - V - F - F."},"answer":"A","source":"Gineco e obstetricia/MED GIN 04/MED GIN 04.txt","sourceLabel":"MED · MED GIN 04","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-04-131681","number":"131681","sourceNumber":"131681","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-04","collectionLabel":"MED · MED GIN 04","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 04","subtopic":"","stem":"Assinale a afirmativa abaixo que contenha os exames complementares essenciais\npara investigação de amenorreia, após exclusão de\ngravidez:","options":{"A":"FSH, TSH, Prolactina e glicemia de jejum;","B":"LH e FSH;","C":"LH, TSH e progesterona;","D":"LH, TSH e prolactina;","E":"FSH e progesterona;"},"answer":"E","source":"Gineco e obstetricia/MED GIN 04/MED GIN 04.txt","sourceLabel":"MED · MED GIN 04","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-04-111649","number":"111649","sourceNumber":"111649","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-04","collectionLabel":"MED · MED GIN 04","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 04","subtopic":"","stem":"A causa mais frequente de pseudo-hermafroditismo feminino é:","options":{"A":"hiperplasia congênita da adrenal;","B":"síndrome do testículo feminilizante;","C":"deficiência da 5 alfa redutase;","D":"síndrome de Savage;","E":"disgenesia gonadal;"},"answer":"A","source":"Gineco e obstetricia/MED GIN 04/MED GIN 04.txt","sourceLabel":"MED · MED GIN 04","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-04-101017","number":"101017","sourceNumber":"101017","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-04","collectionLabel":"MED · MED GIN 04","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 04","subtopic":"","stem":"Paciente de 28 anos, sempre teve ciclos menstruais regulares, vida sexual ativa,\nausência de galactorreia e apresentando\namenorreia há 05 meses. Quais os 03 principais exames\nlaboratoriais que devem ser solicitados antes do teste da progesterona?","options":{"A":"FSH, LH, Estradiol.","B":"B-HCG, TSH, FSH.","C":"B-HCG, TSH, Prolactina.","D":"B-HCG, FSH, Prolactina.","E":"FSH, TSH, Estradiol."},"answer":"C","source":"Gineco e obstetricia/MED GIN 04/MED GIN 04.txt","sourceLabel":"MED · MED GIN 04","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-04-102760","number":"102760","sourceNumber":"102760","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-04","collectionLabel":"MED · MED GIN 04","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 04","subtopic":"","stem":"Em relação à genitália externa e interna, assinale a alternativa INCORRETA.","options":{"A":"As glândulas genitais acessórias femininas desenvolvem-se como evaginações da uretra e do\nseio urogenital definitivo.","B":"O fórnice posterior da vagina está separado do fundo de saco posterior de Douglas pela parede\nvaginal e pelo peritônio.","C":"As artérias uterinas são ramos das ilíacas internas e se anastomosam com as artérias ovarianas\ne vaginais.","D":"A flexão uterina é a relação entre o eixo que passa pelo canal cervical com o eixo que passa\npela vagina."},"answer":"D","source":"Gineco e obstetricia/MED GIN 04/MED GIN 04.txt","sourceLabel":"MED · MED GIN 04","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-04-106396","number":"106396","sourceNumber":"106396","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-04","collectionLabel":"MED · MED GIN 04","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 04","subtopic":"","stem":"Sobre o hirsutismo e a produção de androgênios na mulher adulta, marque a afirmativa\nINCORRETA:","options":{"A":"A maior parte da testosterona circulante é proveniente de conversão periférica da\nandrostenediona.","B":"A suprarrenal é a principal produtora de S-DHEA e DHEA.","C":"A testosterona é transformada em di-hidrotestosterona por ação da 5-alfarredutase.","D":"A principal ação do acetato de ciproterona é a inibição da 5-alfarredutase.","E":"A obesidade aumenta a conversão periférica de androstenediona em testosterona, aumentando\nos níveis de SHBG (proteína carreadora de\nhormônios sexuais)."},"answer":"E","source":"Gineco e obstetricia/MED GIN 04/MED GIN 04.txt","sourceLabel":"MED · MED GIN 04","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-04-106420","number":"106420","sourceNumber":"106420","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-04","collectionLabel":"MED · MED GIN 04","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 04","subtopic":"","stem":"Mulher de 22 anos compareceu ao ambulatório com queixa de amenorreia primária.\nInstituiu-se prova terapêutica com progestágeno,\nque apresentou resultado negativo. Também não\nhouve resposta ao estímulo estroprogestínico. A provável causa da amenorreia é:","options":{"A":"uterina","B":"ovariana","C":"hipofisária","D":"hipotalâmica","E":"suprarrenal"},"answer":"A","source":"Gineco e obstetricia/MED GIN 04/MED GIN 04.txt","sourceLabel":"MED · MED GIN 04","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-04-88879","number":"88879","sourceNumber":"88879","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-04","collectionLabel":"MED · MED GIN 04","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 04","subtopic":"","stem":"Dos seguintes achados ao exame físico: I. Ausência de pelos pubianos. II. Vagina\ncurta. III. Nodulação em região inguinal.\nQuais sugerem alteração cromossômica em menina de 18\nanos com amenorreia primária?","options":{"A":"Apenas I.","B":"Apenas II.","C":"Apenas III.","D":"Apenas I e III.","E":"I, II e III."},"answer":"E","source":"Gineco e obstetricia/MED GIN 04/MED GIN 04.txt","sourceLabel":"MED · MED GIN 04","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-04-88908","number":"88908","sourceNumber":"88908","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-04","collectionLabel":"MED · MED GIN 04","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 04","subtopic":"","stem":"São exames complementares recomendados na investigação inicial da amenorreia\nsecundária:","options":{"A":"LH, FSH, e progesterona.","B":"ß-HCG, LH e FSH.","C":"ß-HCG, TSH e prolactina.","D":"ß-HCG e ultrassonografia transvaginal.","E":"Testosterona total, 17(OH) progesterona e prolactina."},"answer":"C","source":"Gineco e obstetricia/MED GIN 04/MED GIN 04.txt","sourceLabel":"MED · MED GIN 04","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-04-88909","number":"88909","sourceNumber":"88909","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-04","collectionLabel":"MED · MED GIN 04","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 04","subtopic":"","stem":"Com relação à Síndrome dos Ovários Policísticos (SOP), analise as afirmações a\nseguir: I. Irregularidade menstrual,\nhirsutismo, obesidade e infertilidade são queixas comuns. II.\nDeve-se rastrear síndrome metabólica. III. O hiperinsulinemismo acomete a maioria das pacientes\nobesas com SOP, sendo um critério diagnóstico. IV. O uso de anticoncepcional combinado oral\npode regularizar o fluxo menstrual, melhorar os efeitos cosméticos e proteger o endométrio nas\npacientes anovuladoras. Quais estão corretas?","options":{"A":"Apenas I e II","B":"Apenas I e III.","C":"Apenas I, II e IV.","D":"Apenas I, III e IV.","E":"I, II, III e IV."},"answer":"C","source":"Gineco e obstetricia/MED GIN 04/MED GIN 04.txt","sourceLabel":"MED · MED GIN 04","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-04-77609","number":"77609","sourceNumber":"77609","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-04","collectionLabel":"MED · MED GIN 04","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 04","subtopic":"","stem":"Muitos estudos têm mostrado de forma conclusiva a associação direta entre Síndrome\ndos Ovários Policísticos (SOP) e várias\npatologias, exceto:","options":{"A":"infertilidade;","B":"osteoporose;","C":"hiperplasia e/ou câncer de endométrio;","D":"doenças cardiovasculares;","E":"diabetes mellitus."},"answer":"B","source":"Gineco e obstetricia/MED GIN 04/MED GIN 04.txt","sourceLabel":"MED · MED GIN 04","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-04-77514","number":"77514","sourceNumber":"77514","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-04","collectionLabel":"MED · MED GIN 04","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 04","subtopic":"","stem":"Paciente com disgenesia gonadal pura não tratada apresenta:","options":{"A":"mamas desenvolvidas;","B":"genitália externa feminina;","C":"ovários aumentados de volume;","D":"implantação baixa de cabelo, baixa estatura e pescoço alado;","E":"ausência de útero."},"answer":"B","source":"Gineco e obstetricia/MED GIN 04/MED GIN 04.txt","sourceLabel":"MED · MED GIN 04","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-04-59078","number":"59078","sourceNumber":"59078","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-04","collectionLabel":"MED · MED GIN 04","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 04","subtopic":"","stem":"Paciente de 27 anos apresentando amenorreia secundária há 06 meses, B-HCG\nnegativo, dosagens de TSH e prolactina normais. Foi administrado Progesterona por 10 dias e\ndepois de 05 dias a paciente menstruou. Qual a hipótese diagnóstica?","options":{"A":"Amenorreia de causa hipotalâmica.","B":"Amenorreia de causa hipofisária.","C":"Amenorreia por falência ovariana prematura.","D":"Amenorreia por causa uterina.","E":"Amenorreia por anovulação crônica."},"answer":"E","source":"Gineco e obstetricia/MED GIN 04/MED GIN 04.txt","sourceLabel":"MED · MED GIN 04","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-04-59085","number":"59085","sourceNumber":"59085","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-04","collectionLabel":"MED · MED GIN 04","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 04","subtopic":"","stem":"Sobre a fisiologia da Prolactina (PRL) é incorreto afirmar:","options":{"A":"O hipotálamo exerce controle predominantemente inibitório sobre a secreção de PRL.","B":"O principal fator inibidor hipotalâmico é a Dopamina (DOPA).","C":"O hormônio liberador de tireotrofina (TRH) e a serotonina também são fatores inibidores da\nprolactina.","D":"A prolactina de molécula pequena (\"little prolactin\") tem alta afinidade pelo receptor e elevada\nbioatividade.","E":"As formas moleculares maiores (\"big prolactin\" e \"big-big prolactin\") têm aparentemente menor\nligação com os receptores."},"answer":"C","source":"Gineco e obstetricia/MED GIN 04/MED GIN 04.txt","sourceLabel":"MED · MED GIN 04","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-04-43293","number":"43293","sourceNumber":"43293","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-04","collectionLabel":"MED · MED GIN 04","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 04","subtopic":"","stem":"Acerca da síndrome dos ovários policísticos, marque a alternativa INCORRETA:","options":{"A":"É uma desordem endócrina comum, afetando mulheres em idade reprodutiva e é causa comum\nde anovulação.","B":"São diagnósticos diferenciais: Síndrome de Cushing; hiperplasia adrenal congênita; tumores\nadrenais produtores de androgênios.","C":"Os sintomas mais comuns são: hirsutismo e obesidade.","D":"Hiperinsulinemia, resistência à insulina e maior tendência a desenvolvimento precoce de\ndiabetes tipo II fazem parte da síndrome.","E":"Para completa caracterização clínica da síndrome é necessária a presença de alterações\nmenstruais, ou amenorreia ou sangramento uterino anormal."},"answer":"E","source":"Gineco e obstetricia/MED GIN 04/MED GIN 04.txt","sourceLabel":"MED · MED GIN 04","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-04-43931","number":"43931","sourceNumber":"43931","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-04","collectionLabel":"MED · MED GIN 04","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 04","subtopic":"","stem":"Em relação à fisiologia da prolactina é correto afirmar, exceto:","options":{"A":"A dopamina (DOPA) é o principal regulador da prolactina, exercendo ação estimulatória sobre\nsua liberação.","B":"TRH, serotonina, GnRH e histamina podem promover aumento da secreção de prolactina.","C":"Quando elevada a prolactina interfere na secreção hipotalâmica de GnRH, desaparecendo a\npulsatilidade do LH e do FSH.","D":"Os lactótrofos da adenoipófise são as células que sintetizam e secretam a prolactina.","E":"A prolactina de molécula pequena (little prolactin) é a forma biologicamente mais ativa."},"answer":"A","source":"Gineco e obstetricia/MED GIN 04/MED GIN 04.txt","sourceLabel":"MED · MED GIN 04","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-04-32495","number":"32495","sourceNumber":"32495","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-04","collectionLabel":"MED · MED GIN 04","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 04","subtopic":"","stem":"Paciente de 32 anos relatando amenorreia há 04 meses. Sempre teve ciclos irregulares\ncom atrasos menstruais. Após Beta-hCG negativo e\nTSH normal. Foi feita prova da progesterona e\na paciente menstruou. Qual a hipótese diagnóstica?","options":{"A":"Amenorreia consequente a alterações do útero ou vias de drenagem.","B":"Amenorreia de causa ovariana (menopausa precoce).","C":"Amenorreia de causa hipofisária.","D":"Amenorreia de causa hipotalâmica.","E":"Amenorreia por anovulação crônica."},"answer":"E","source":"Gineco e obstetricia/MED GIN 04/MED GIN 04.txt","sourceLabel":"MED · MED GIN 04","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-04-23076","number":"23076","sourceNumber":"23076","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-04","collectionLabel":"MED · MED GIN 04","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 04","subtopic":"","stem":"Marque a correta sequência de eventos na fisiopatologia da anovulação crônica:","options":{"A":"Resistência insulínica, hiperinsulinismo, hirsutismo.","B":"Hiperinsulinismo, resistência insulínica, hirsutismo.","C":"Obesidade, hiperinsulinismo, resistência insulínica.","D":"Hirsutismo, resistência insulínica, hiperinsulinismo.","E":"Obesidade hirsutismo, resistência insulínica."},"answer":"A","source":"Gineco e obstetricia/MED GIN 04/MED GIN 04.txt","sourceLabel":"MED · MED GIN 04","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 04","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-04-9391","number":"9391","sourceNumber":"9391","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-04","collectionLabel":"MED · MED GIN 04","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 04","subtopic":"","stem":"Os ductos paramesonéfricos originam:","options":{"A":"Cisto Gartner.","B":"Epoóforo.","C":"Trompas de Falópio.","D":"Paraóforo.","E":"Cisto Nuck."},"answer":"C","source":"Gineco e obstetricia/MED GIN 04/MED GIN 04.txt","sourceLabel":"MED · MED GIN 04","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-04-8152","number":"8152","sourceNumber":"8152","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-04","collectionLabel":"MED · MED GIN 04","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 04","subtopic":"","stem":"Quanto à anovulação crônica é incorreto afirmar:","options":{"A":"As pacientes com síndrome de ovários policísticos e obesas podem apresentar intolerância a\nglicose.","B":"A acantose Nigricans é considerada um marcador de resistência à insulina nas mulheres\nhirsutas.","C":"Nas pacientes anovulatórias crônicas, a elevação persistente dos níveis de estrogênios não\ninterrompidos por progesterona aumenta o risco de carcinoma endometrial.","D":"A redução de peso nas pacientes obesas com síndrome de ovários policísticos pode afetar\npositivamente as normalidades menstruais e o hirsutismo.","E":"Os contraceptivos orais são pouco eficazes por diminuir a produção ovariana de androgênios e\ntambém diminuem os níveis circulantes de globulina transportadora de hormônios sexuais."},"answer":"E","source":"Gineco e obstetricia/MED GIN 04/MED GIN 04.txt","sourceLabel":"MED · MED GIN 04","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-04-355617","number":"355617","sourceNumber":"355617","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-04","collectionLabel":"MED · MED GIN 04","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 04","subtopic":"","stem":"Relacione a Coluna 1 à Coluna 2, associando as síndromes às suas respectivas\nmanifestações: Coluna 1; 1. síndrome de Morris;\n2. síndrome de Savage; 3. síndrome de Turner; 4.\nsíndrome de Rokitansky; 5. síndrome de Kallmann; Coluna 2; ( ) amenorreia hipergonadotrófica,\nalteração no receptor de gonadotrofinas, ausência de mamas e presença de pelos pubianos; ( )\namenorreia hipogonadotrófica, anosmia, ausência de mamas e presença de pelos pubianos; ( )\namenorreia hipergonadotrófica, disgenesia gonadal, ausência de mamas e presença de pelos\npubianos; ( ) amenorreia hipergonadotrófica, ausência de pelos pubianos e presença de mamas; ( )\namenorreia normogonadotrófica, defeito mülleriano, presença de mamas e de pelos pubianos; A\nordem correta de preenchimento dos parênteses, de cima para baixo, é:","options":{"A":"1 ? 2 ? 3 ? 4 ? 5","B":"2 ? 5 ? 3 ? 1 ? 4","C":"3 ? 1 ? 4 ? 5 ? 2","D":"5 ? 1 ? 3 ? 4 ? 2","E":"4 ? 3 ? 1 ? 2 ? 5"},"answer":"A","source":"Gineco e obstetricia/MED GIN 04/MED GIN 04.txt","sourceLabel":"MED · MED GIN 04","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 04","MED"],"answerSource":"inferred","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-04-366914","number":"366914","sourceNumber":"366914","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-04","collectionLabel":"MED · MED GIN 04","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 04","subtopic":"","stem":"Uma paciente de 16 anos é encaminhada ao seu consultório de ginecologia após ter\nsua primeira menstruação muito tardia. A\nanamnese revela que ela tem estatura mais baixa que\nseus pares e um exame físico demonstra uma envergadura de asa mais longa que sua altura. Com\nbase nos Critérios de Turner, qual das seguintes características você esperaria encontrar em seu\nexame?","options":{"A":"Linha de cabelo baixa na nuca.","B":"Ovários multifoliculares ao ultrassom.","C":"Ausência de dismorfia facial.","D":"Presença de gônadas masculinas."},"answer":"A","source":"Gineco e obstetricia/MED GIN 04/MED GIN 04.txt","sourceLabel":"MED · MED GIN 04","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-04-353801","number":"353801","sourceNumber":"353801","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-04","collectionLabel":"MED · MED GIN 04","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 04","subtopic":"","stem":"Sobre a síndrome dos ovários policísticos, julgue as seguintes afirmações como\nverdadeiras (V) ou falsas (F). 1. A perda de\npeso, em pacientes obesas, ajuda na melhora do\nquadro clínico. 2. O diagnóstico é feito apenas através da ressonância magnética da pelve. 3.\nHirsutismo, acne, infertilidade e alterações menstruais são alguns dos sintomas que podem estar\npresentes. Sendo (V) para verdadeiro e (F) para falso, é CORRETO afirmar:","options":{"A":"1V ? 2F ? 3V.","B":"1V ? 2V ? 3F.","C":"1F ? 2F ? 3V.","D":"1F ? 2V ? 3F."},"answer":"A","source":"Gineco e obstetricia/MED GIN 04/MED GIN 04.txt","sourceLabel":"MED · MED GIN 04","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-04-362645","number":"362645","sourceNumber":"362645","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-04","collectionLabel":"MED · MED GIN 04","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 04","subtopic":"","stem":"Uma mulher de 20 anos procura o ginecologista referindo amenorreia primária. Nega\nrelações sexuais. O desenvolvimento estatural e de caracteres sexuais secundários é normal. Ao\nexame físico o ginecologista nota vagina curta terminando em fundo cego. Solicitado cariótipo, cujo\nresultado foi 46XX. O diagnóstico mais provável é síndrome de:","options":{"A":"Morris","B":"Rokitansky-Kuster-Hauser","C":"Sheehan","D":"Kallman"},"answer":"B","source":"Gineco e obstetricia/MED GIN 04/MED GIN 04.txt","sourceLabel":"MED · MED GIN 04","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-04-362644","number":"362644","sourceNumber":"362644","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-04","collectionLabel":"MED · MED GIN 04","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 04","subtopic":"","stem":"Mulher de 23 anos com quadro de hirsutismo importante e irregularidade menstrual\nprocura ajuda do ginecologista. Serão necessárias\nalgumas dosagens hormonais e exames de\nimagem para fechar o diagnóstico. Para uma correta interpretação dos resultados, o obstetra tem\nque saber que os ovários são incapazes de produzir:","options":{"A":"Desidroepiandrostenediona.","B":"Testosterona.","C":"Estradiol.","D":"Androstenediona."},"answer":"A","source":"Gineco e obstetricia/MED GIN 04/MED GIN 04.txt","sourceLabel":"MED · MED GIN 04","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-04-354775","number":"354775","sourceNumber":"354775","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-04","collectionLabel":"MED · MED GIN 04","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 04","subtopic":"","stem":"Leia o caso clínico a seguir. Mulher, 22 anos de idade, foi ao ambulatório de\nginecologia com queixa de irregularidade do\nciclo menstrual, usava anticoncepcional oral\ncombinado para menstruar, porém parou há 6 meses, pois deseja engravidar. Desde então a\nmenstruação não ocorreu. Ao exame físico IMC: 35 kg/m², hirsutismo e acne. A ultrassonografia\ntransvaginal mostra múltiplos cistos hipoecoicos pequenos. Para conduzir esse caso, o\nginecologista pode recomendar:","options":{"A":"o uso de metformina como droga de escolha para indução ovariana.","B":"a perda de 5 a 10% do peso, para melhora da irregularidade menstrual.","C":"o uso de citrato de clomifeno, para regularização do ciclo menstrual.","D":"a ministração do inositol, como primeira opção para regulação da menstruação."},"answer":"B","source":"Gineco e obstetricia/MED GIN 04/MED GIN 04.txt","sourceLabel":"MED · MED GIN 04","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-04-354846","number":"354846","sourceNumber":"354846","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-04","collectionLabel":"MED · MED GIN 04","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 04","subtopic":"","stem":"A síndrome de ovários policísticos (SOP) é uma das afecções mais associadas a\namenorreia secundária e um dos seus critérios é a alteração menstrual. De acordo com os novos\nconceitos (2018), são características da paciente que apresenta alteração menstrual associada à\nSOP:","options":{"A":"menina de 15 anos, com menarca aos 13 anos, com ciclos menstruais de 40 dias.","B":"menina de 16 anos, com menarca aos 11 anos e ciclos menstruais de 40 dias.","C":"mulher de 33 anos, com queixa de parada da menstruação há 60 dias.","D":"mulher de 48 anos, com queixa de parada da menstruação há um ano."},"answer":"B","source":"Gineco e obstetricia/MED GIN 04/MED GIN 04.txt","sourceLabel":"MED · MED GIN 04","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-04-331983","number":"331983","sourceNumber":"331983","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-04","collectionLabel":"MED · MED GIN 04","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 04","subtopic":"","stem":"Paciente procura atendimento apresentando quadro clínico de amenorreia. Os exames\nfísico e ginecológico foram normais. A\ndosagem quantitativa de B-HCG foi negativa. Após teste do\nestrogênio e da progesterona, a mulher não apresentou sangramento. Nesse contexto, a melhor\nexplicação para o caso é uma lesão do compartimento:","options":{"A":"Ovariano.","B":"Uterino.","C":"Hipofisário.","D":"Hipotalâmico.","E":"Hipotalâmico e hipofisário."},"answer":"D","source":"Gineco e obstetricia/MED GIN 04/MED GIN 04.txt","sourceLabel":"MED · MED GIN 04","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-04-337439","number":"337439","sourceNumber":"337439","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-04","collectionLabel":"MED · MED GIN 04","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 04","subtopic":"","stem":"Uma paciente com amenorreia é tratada com pílula combinada por 21 dias e após a\ninterrupção não apresenta sangramento. A causa mais provável é:","options":{"A":"ovariana.","B":"hipofisária.","C":"endometrial.","D":"tumoral."},"answer":"C","source":"Gineco e obstetricia/MED GIN 04/MED GIN 04.txt","sourceLabel":"MED · MED GIN 04","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-04-337441","number":"337441","sourceNumber":"337441","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-04","collectionLabel":"MED · MED GIN 04","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 04","subtopic":"","stem":"A paciente que tem o ?perfil? típico da Síndrome dos Ovários Policísticos é:","options":{"A":"obesa, hirsuta e infértil.","B":"magra, infértil e com alopecia.","C":"obesa, hirsuta e com fertilidade normal.","D":"magra, hirsuta e infértil."},"answer":"A","source":"Gineco e obstetricia/MED GIN 04/MED GIN 04.txt","sourceLabel":"MED · MED GIN 04","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-04-300900","number":"300900","sourceNumber":"300900","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-04","collectionLabel":"MED · MED GIN 04","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 04","subtopic":"","stem":"Paciente de 42 anos, gesta 7 para 3 aborto 4, cursando com amenorreia nos últimos 6\nmeses. Exames de FSH, prolactina e TSH normais. Realizado teste de estimulação com estrogênio\n\n+ progesterona que resultou negativo. A MAIS provável hipótese diagnóstica nesse caso é:","options":{"A":"menopausa.","B":"anovulação crônica.","C":"hipotiroidismo subclínico.","D":"sinéquia uterina."},"answer":"D","source":"Gineco e obstetricia/MED GIN 04/MED GIN 04.txt","sourceLabel":"MED · MED GIN 04","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-04-308220","number":"308220","sourceNumber":"308220","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-04","collectionLabel":"MED · MED GIN 04","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 04","subtopic":"","stem":"A síndrome dos ovários policísticos apresenta sinais e, entre eles, podemos encontrar a\nacantose nigricans. Das opções abaixo, qual explica melhor esse achado?","options":{"A":"Hipoandrogenismo.","B":"Hipogonadismo.","C":"Hiperandrogenismo.","D":"Resistência insulínica periférica."},"answer":"D","source":"Gineco e obstetricia/MED GIN 04/MED GIN 04.txt","sourceLabel":"MED · MED GIN 04","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-04-308224","number":"308224","sourceNumber":"308224","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-04","collectionLabel":"MED · MED GIN 04","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 04","subtopic":"","stem":"Em uma mulher de 32 anos com FSH sérico elevado associado a o quadro de\namenorreia secundária, o diagnóstico mais provável é:","options":{"A":"Falência ovariana precoce.","B":"Agenesia ovariana.","C":"Síndrome do ovário policístico.","D":"Síndrome de Sheehan."},"answer":"A","source":"Gineco e obstetricia/MED GIN 04/MED GIN 04.txt","sourceLabel":"MED · MED GIN 04","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-04-294268","number":"294268","sourceNumber":"294268","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-04","collectionLabel":"MED · MED GIN 04","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 04","subtopic":"","stem":"Paciente mulher, de 31 anos, com queixa de aumento de pelos terminais em face,\nmembros superiores, tórax e face, de início logo\napós a puberdade, de caráter progressivo. Índice\nde massa corpórea de 27,8 k/m². Ciclos menstruais regulares. Escore de Ferriman-Gallwey: 18\npontos. Avaliação laboratorial com níveis de andrógenos normais, em duas ocasiões diferentes. De\nacordo com os dados, para esta paciente:","options":{"A":"a síndrome de ovários policísticos (SOPC) é uma das principais hipóteses diagnósticas, por ser\na principal causa de hirsutismo em mulheres em\nidade reprodutiva e pelo quadro clínico laboratorial\napresentado.","B":"o diagnóstico de hirsutismo não pode ser feito, pela ausência de hiperandrogenemia.","C":"a presença de ciclos menstruais regulares exclui o diagnóstico de SOPC.","D":"a terapia inicial com antiandrógenos em monoterapia seria preferível ao uso de contraceptivo\noral, pelo menor impacto metabólico."},"answer":"A","source":"Gineco e obstetricia/MED GIN 04/MED GIN 04.txt","sourceLabel":"MED · MED GIN 04","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-04-316333","number":"316333","sourceNumber":"316333","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-04","collectionLabel":"MED · MED GIN 04","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 04","subtopic":"","stem":"A.M.P., 17 anos, comparece ao consultório acompanhada de sua mãe, com queixa de\nnunca ter menstruado. Questionada, não\napresentava nenhuma outra queixa clínica. Ao exame\nfísico, as mamas são pouco desenvolvidas para a idade, pelos pubianos escassos e a genitália é\nde aspecto infantil. Após 21 dias de anticoncepcional hormonal oral combinado, prescrito por outro\nginecologista, a paciente menstruou após 5 dias de pausa. Com base nesses dados, assinale a\nalternativa correta:","options":{"A":"Se o FSH e o LH estiverem normais, trata-se de síndrome de Ascherman.","B":"Solicitar ultrassonografia pélvica, pois a principal hipótese diagnóstica é de síndrome de\nRokitansky.","C":"A principal hipótese diagnóstica é a síndrome de Morris.","D":"Solicitar cariótipo da paciente pela possibilidade de síndrome de Turner."},"answer":"D","source":"Gineco e obstetricia/MED GIN 04/MED GIN 04.txt","sourceLabel":"MED · MED GIN 04","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-04-311928","number":"311928","sourceNumber":"311928","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-04","collectionLabel":"MED · MED GIN 04","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 04","subtopic":"","stem":"Mulher de 23 anos, em consulta ginecológica, afirma que possui ciclos menstruais\nirregulares e muitas vezes com intervalos\nlongos. Ao examinar, encontramos a presença de pelos\nem face, raiz de coxa e dorso. Ela leva na consulta uma ultrassonografia endovaginal com ovários\napresentando vinte e um folículos antrais. Está tentando engravidar há dois meses. De acordo com\nesse relato, como podemos orientá-la?","options":{"A":"A sua reserva ovariana é muito boa, continue tentando até completar um ano.","B":"O uso de indutores de ovulação está contraindicado nessa situação.","C":"Suas chances de engravidar são mínimas devido ao ovário multifolicular.","D":"O uso de metformina pode auxiliar no retorno da ovulação."},"answer":"D","source":"Gineco e obstetricia/MED GIN 04/MED GIN 04.txt","sourceLabel":"MED · MED GIN 04","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-04-311938","number":"311938","sourceNumber":"311938","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-04","collectionLabel":"MED · MED GIN 04","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 04","subtopic":"","stem":"Paciente, 30 anos, queixa-se de amenorreia após uma curetagem uterina para\ntratamento de sangramento pós-parto. Qual o diagnóstico mais provável?","options":{"A":"Disgenesia gonadal.","B":"Síndrome de Sheehan.","C":"Síndrome de Asherman.","D":"Síndrome de Kallmann."},"answer":"C","source":"Gineco e obstetricia/MED GIN 04/MED GIN 04.txt","sourceLabel":"MED · MED GIN 04","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-04-315817","number":"315817","sourceNumber":"315817","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-04","collectionLabel":"MED · MED GIN 04","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 04","subtopic":"","stem":"Em paciente onde o diagnóstico é duvidoso entre Síndrome dos Ovários Policísticos e\nHiperplasia Adrenal, o melhor exame para elucidação diagnóstica é:","options":{"A":"FSH.","B":"Estradiol.","C":"Progesterona.","D":"17 alfa-hidroxiprogesterona."},"answer":"D","source":"Gineco e obstetricia/MED GIN 04/MED GIN 04.txt","sourceLabel":"MED · MED GIN 04","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-04-295393","number":"295393","sourceNumber":"295393","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-04","collectionLabel":"MED · MED GIN 04","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 04","subtopic":"","stem":"As amenorreias são classificadas em primárias e secundárias e podem ter causas\nhipoptalâmico-hipofisárias, anovulatórias, ovarianas, hiperprolactinêmicas e do trato excretor. A\namenorreia","options":{"A":"do tipo síndrome de Kalmann e anorexia nervosa são de causas ovarianas.","B":"do tipo secundária, por aumento da prolactina, é decorrente do hímen imperfurado e septo\nvaginal transverso.","C":"por anomalia do trato excretor, são exemplos das decorrentes da gestação e amamentação.","D":"da disfunção do eixo hipotálamo hipófise, são exemplos de síndrome dos ovários\nmicropolicísticos e a anovulação crônica."},"answer":"D","source":"Gineco e obstetricia/MED GIN 04/MED GIN 04.txt","sourceLabel":"MED · MED GIN 04","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-04-294310","number":"294310","sourceNumber":"294310","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-04","collectionLabel":"MED · MED GIN 04","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 04","subtopic":"","stem":"A investigação inicial de amenorreia secundária, excluindo-se a gravidez, deve ser feita\npela","options":{"A":"ultrassonografia pélvica e dosagem de FSH.","B":"ultrassonografia pélvica e dosagem de prolactina.","C":"dosagem no sangue de FSH, TSH e prolactina.","D":"dosagem no sangue de FSH, prolactina e estradiol."},"answer":"C","source":"Gineco e obstetricia/MED GIN 04/MED GIN 04.txt","sourceLabel":"MED · MED GIN 04","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-04-317984","number":"317984","sourceNumber":"317984","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-04","collectionLabel":"MED · MED GIN 04","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 04","subtopic":"","stem":"Mulher de 35 anos refere amenorreia após o último parto, há cerca de um ano. Tem\nantecedentes de três gestações e três cesarianas, tendo sido laqueada na última. O exame físico\ngeral está normal, enquanto o exame ginecológico mostra uma discreta hipotrofia da mucosa\nvaginal. Nos exames laboratoriais, verificam-se as dosagens de FSH = 50 mUl/mL, Estradiol = 20\npg/mL, TSH = 5,3 mU/L e Prolactina = 26 ng/mL. Diante deste quadro, a hipótese diagnóstica é","options":{"A":"hipotiroidismo.","B":"hiperprolactinemia.","C":"falência ovariana precoce.","D":"síndrome dos ovários policísticos."},"answer":"C","source":"Gineco e obstetricia/MED GIN 04/MED GIN 04.txt","sourceLabel":"MED · MED GIN 04","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-04-313244","number":"313244","sourceNumber":"313244","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-04","collectionLabel":"MED · MED GIN 04","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 04","subtopic":"","stem":"Uma paciente de 18 anos procurou a Ginecologia Endócrina com quadro de amenorreia\nsecundária associado a galactorréia e diminuição do campo visual. A dosagem de prolactina\nencontrava-se normal, entretanto na ressonância nuclear magnética, observou-se grande tumor\nhipofisário com a compressão do quiasma óptico. Assinale a alternativa que apresenta a conduta\nmais adequada para o diagnóstico da paciente:","options":{"A":"repetir a prolactina em 3 meses","B":"solicitar uma biópsia de hipófise","C":"solicitar a diluição da amostra por se tratar de efeito gancho","D":"solicitar a dosagem da macroprolactina"},"answer":"C","source":"Gineco e obstetricia/MED GIN 04/MED GIN 04.txt","sourceLabel":"MED · MED GIN 04","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-04-300870","number":"300870","sourceNumber":"300870","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-04","collectionLabel":"MED · MED GIN 04","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 04","subtopic":"","stem":"A Síndrome do Ovário Policístico (SOP) é um distúrbio endócrino mais recorrente nas\nmulheres em idade reprodutiva e a causa mais comum de infertilidade. Frequentemente se\nmanifesta durante a adolescência e é caracterizada por disfunção ovulatória e hiperandrogenismo.\nQuanto ao quadro clínico da Síndrome dos Ovários Policísticos, é CORRETO afirmar:","options":{"A":"Meninas adolescentes com SOP raramente apresentam hirsutismo, acne resistente ao\ntratamento, irregularidades menstruais, acantose\nnigricante e/ou obesidade. Qualquer um desses\nachados pode inicialmente ser a única característica da síndrome, embora uma característica não\nseja suficiente para estabelecer o diagnóstico.","B":"A amenorreia e a oligomenorreia são consequências do estado de anovulação que não forma\ncorpo lúteo e, por isso, produz progesterona.\nAmenorreia secundária ocorre quando existem ciclos\nmenstruais prévios, porém ocorre ausência de pelo menos três ciclos menstruais em mulheres com\nciclos regulares ou ausência de menstruação por, pelo menos, seis meses em mulheres com ciclos\nirregulares.","C":"As manifestações do hiperandrogenismo na SOP são principalmente a acne, o hirsutismo e/ou a\nalopecia androgênica. O hirsutismo é definido clinicamente como uma quantidade anormal de\ncabelo sexual que aparece em um padrão masculino. É comumente classificado de acordo com o\nSistema Ferriman-Gallwey, que quantifica a extensão do crescimento do cabelo nas áreas mais\nsensíveis aos andrógenos.","D":"A alopecia é uma manifestação comum de hiperandrogenemia em adolescentes. Quando\nocorre, pode ser tanto o padrão masculino,\nafetando o couro cabeludo fronto-temporo-occipita,\nquanto o feminino, afetando a coroa, tipicamente se manifestando cedo como uma parte da linha\nmédia alargada em um padrão de ?árvore de Natal?."},"answer":"C","source":"Gineco e obstetricia/MED GIN 04/MED GIN 04.txt","sourceLabel":"MED · MED GIN 04","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-04-281999","number":"281999","sourceNumber":"281999","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-04","collectionLabel":"MED · MED GIN 04","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 04","subtopic":"","stem":"Considerando os critérios de Rotterdam (2003), como é feito o diagnóstico da síndrome\ndos ovários policísticos?","options":{"A":"Oligo-ovulação ou anovulação, hiperandrogenismo e ovários policísticos (todos têm que estar\npresentes).","B":"Oligo-ovulação ou anovulação, hiperandrogenismo e ovários policísticos (pelo menos dois\ndevem estar presentes).","C":"Aumento da resistência periférica à insulina, hiperandrogenismo e ovários policísticos (todos têm\nque estar presentes).","D":"Aumento da resistência periférica à insulina, hipertricose e ovários policísticos (pelo menos\ndois\ndevem estar presentes)."},"answer":"B","source":"Gineco e obstetricia/MED GIN 04/MED GIN 04.txt","sourceLabel":"MED · MED GIN 04","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-04-274783","number":"274783","sourceNumber":"274783","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-04","collectionLabel":"MED · MED GIN 04","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 04","subtopic":"","stem":"Mulher de 20 anos procura atendimento com queixa de ciclos menstruais irregulares\ndesde a menarca e presença de pelos em\nregião de face, raiz de coxa. No momento não pensa em\ngravidez. Traz exames normais de TSH, prolactina e FSH. Sulfato de deidroepiandrostenediona\n\n(S-DHEA) levemente aumentado. Ecografia vaginal com mais de 20 folículos antrais. Qual dos\nseguintes itens é a melhor conduta para essa paciente?","options":{"A":"Inserir um DIU hormonal, pois melhora o hirsutismo.","B":"Prescrever anticoncepcional hormonal combinado, para regularizar ciclo.","C":"Deve ser tratada obrigatoriamente com acetato de ciproterona.","D":"Indicar cirurgia para reduzir os folículos."},"answer":"B","source":"Gineco e obstetricia/MED GIN 04/MED GIN 04.txt","sourceLabel":"MED · MED GIN 04","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-04-277437","number":"277437","sourceNumber":"277437","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-04","collectionLabel":"MED · MED GIN 04","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 04","subtopic":"","stem":"A amenorreia primária é a não ocorrência da menarca aos 14 anos, sem presença dos\ncaracteres sexuais secundários, ou até os 16 anos, com caracteres sexuais secundários. A respeito\nda amenorreia primária, assinale a alternativa correta:","options":{"A":"na síndrome de Turner, os ovários não são funcionantes ou têm uma vida média curta. Poderá\nhaver coarctação de aorta, rim \"\"em ferradura\"\" e\nbaixa estatura","B":"na agenesia uterovaginal (síndrome de Rokitansky), cujo cariótipo é XX, o tratamento clássico\nconsiste em estrogenoterapia e cirurgia para neovaginoplastia","C":"na disgenesia gonadal pura (síndrome de Swyer), o cariótipo é 46,XY, e o testículo produz\nestradiol e o Fator Inibidor Mülleriano (FIM)","D":"na síndrome de Morris, cujo cariótipo é XX, devemos extirpar a gônada após a puberdade\ndevido ao risco de malignização"},"answer":"A","source":"Gineco e obstetricia/MED GIN 04/MED GIN 04.txt","sourceLabel":"MED · MED GIN 04","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-04-274791","number":"274791","sourceNumber":"274791","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-04","collectionLabel":"MED · MED GIN 04","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 04","subtopic":"","stem":"A síndrome dos Ovários Policísticos (SOP) foi descrita por Stein e Leventhal em 1935.\nMesmo após tanto tempo de sua descoberta, essa afecção ainda é um enigma para muitos\npesquisadores. Sobre essa doença podemos afirmar que:","options":{"A":"faz parte da propedêutica inicial solicitar TSH, cortisol, Testosterona total, DHEA, FSH e Lh.","B":"a atividade física e a perda de peso melhoram os ciclos ovulatórios, porém, não melhoram o\nhiperandrogenismo cutâneo.","C":"a espirolactona é um fármaco que pode ser utilizado para o tratamento do androgenismo\ncutâneo.","D":"o uso da metformina em pacientes com SOP não tem benefícios na ovulação."},"answer":"C","source":"Gineco e obstetricia/MED GIN 04/MED GIN 04.txt","sourceLabel":"MED · MED GIN 04","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-04-281300","number":"281300","sourceNumber":"281300","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-04","collectionLabel":"MED · MED GIN 04","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 04","subtopic":"","stem":"Paciente de 38 anos com obesidade grau 3, ciclos menstruais longos, com intervalos\nde até 4 meses sem menstruar. Ao ultrassom,\nficam evidentes múltiplos microcistos ovarianos\nperiféricos bilaterais. A melhor abordagem desse caso é:","options":{"A":"Anticoncepcional combinado oral.","B":"Danazol.","C":"Análogo do GnRH.","D":"Drilling ovariano bilateral."},"answer":"A","source":"Gineco e obstetricia/MED GIN 04/MED GIN 04.txt","sourceLabel":"MED · MED GIN 04","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-04-273192","number":"273192","sourceNumber":"273192","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-04","collectionLabel":"MED · MED GIN 04","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 04","subtopic":"","stem":"Paciente, 14 anos, com ausência de menstruação e de crescimento dos caracteres\nsexuais secundários, vagina sólida até seu quinto\ninferior, útero rudimentar em forma de cordões\nbicornes com função ovariana e o cariótipo feminino normais, sem anormalidades do trato urinário,\ndiagnóstico de:","options":{"A":"Septo vaginal transverso.","B":"Síndrome da insensibilidade a andrógenos.","C":"Síndrome de Rokitansky-Kuster-Hauser.","D":"Hímen imperfurado."},"answer":"C","source":"Gineco e obstetricia/MED GIN 04/MED GIN 04.txt","sourceLabel":"MED · MED GIN 04","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-04-232213","number":"232213","sourceNumber":"232213","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-04","collectionLabel":"MED · MED GIN 04","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 04","subtopic":"","stem":"A fratura por estresse, lesão decorrente de uma carga anormal sobre um osso normal,\né mais comum em mulheres, com um risco\nrelativo de até doze vezes maior, quando comparadas\naos homens. A tríade da mulher atleta caracteriza-se pela presença de","options":{"A":"distúrbios hormonais, amenorreia e osteoporose.","B":"distúrbios dietéticos, amenorreia e osteoporose.","C":"distúrbios dietéticos, distúrbios hormonais e osteoporose.","D":"distúrbios hormonais, amenorreia e osteopenia."},"answer":"B","source":"Gineco e obstetricia/MED GIN 04/MED GIN 04.txt","sourceLabel":"MED · MED GIN 04","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-04-231951","number":"231951","sourceNumber":"231951","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-04","collectionLabel":"MED · MED GIN 04","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 04","subtopic":"","stem":"São achados clínicos em paciente com síndrome da insensibilidade aos androgênios\nforma completa:","options":{"A":"ambiguidade da genitália externa e hipotrofia dos derivados müllerianos","B":"estatura baixa e ausência de mamas","C":"mamas normais e útero infantil","D":"genitália externa feminina e ausência de útero","E":"vagina curta e útero infantil"},"answer":"D","source":"Gineco e obstetricia/MED GIN 04/MED GIN 04.txt","sourceLabel":"MED · MED GIN 04","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-04-249879","number":"249879","sourceNumber":"249879","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-04","collectionLabel":"MED · MED GIN 04","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 04","subtopic":"","stem":"Adolescente, de 16 anos, com queixa de ciclos menstruais irregulares desde a\nmenarca, intercalando intervalos menstruais de\n15/15 dias, com atrasos de até um mês, associados\na menstruações com volume aumentado, sem dismenorreia. Tem antecedentes de menarca aos 10\nanos e ausência de sexarca. Este quadro clinico é compatível com sangramento uterino","options":{"A":"anormal, característico da adolescência.","B":"anormal, característico de anovulia crônica.","C":"anormal, característico de imaturidade do eixo.","D":"fisiológico, próprio da puberdade."},"answer":"B","source":"Gineco e obstetricia/MED GIN 04/MED GIN 04.txt","sourceLabel":"MED · MED GIN 04","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-04-254266","number":"254266","sourceNumber":"254266","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-04","collectionLabel":"MED · MED GIN 04","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 04","subtopic":"","stem":"Em relação à paciente com amenorreia secundária e que sangra após administração de\n100 mg de progesterona IM, pode-se dizer\nque tem:","options":{"A":"Alteração ao nível do trato mulleriano.","B":"Falência ovariana.","C":"Falência hipofisária.","D":"Nível estrogênico razoável."},"answer":"D","source":"Gineco e obstetricia/MED GIN 04/MED GIN 04.txt","sourceLabel":"MED · MED GIN 04","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 04","MED"],"answerSource":"explicit","commentDeferred":true},{"id":"med-gineco-e-obstetricia-med-gin-04-254267","number":"254267","sourceNumber":"254267","collectionBlock":"med:med-gineco-e-obstetricia-med-gin-04","collectionLabel":"MED · MED GIN 04","documentBlock":"","area":"Ginecologia e Obstetrícia","specialty":"Ginecologia e Obstetrícia","topic":"MED GIN 04","subtopic":"","stem":"Paciente com amenorreia primária e bom desenvolvimento de caracteres sexuais\nsecundários sugere:","options":{"A":"Alteração ao nível hipotalâmico.","B":"Alteração ao nível ovariano.","C":"Alteração ao nível do tato mulleriano.","D":"Alteração do nível hipofisário."},"answer":"C","source":"Gineco e obstetricia/MED GIN 04/MED GIN 04.txt","sourceLabel":"MED · MED GIN 04","images":[],"optionImages":{},"commentImages":[],"tags":["Ginecologia e Obstetrícia","MED GIN 04","MED"],"answerSource":"explicit","commentDeferred":true}]};
